    const steps = applies.map((o) => ({ id: o.id, type: o.type, do: o.requirement, noticeHours: o.noticeHours || 0, party: o.party, source: o.source, verified: o.verified }));
    const km = wo.kmFrom != null ? `km ${wo.kmFrom}` : wo.segment;
